SELECT COUNT(1)
FROM sys_menu
WHERE pid = #{pid}

SELECT COUNT(1)
FROM sys_menu
WHERE name = #{name}
  AND path = #{path}
  AND component = #{component}
  AND pid = #{pid}
  AND menu_type_cd != '1002003'
  AND del_flag = 'F'

